async function adminPost(request: Request, env: RuntimeEnv, url: URL, user: User, ctx: ExecutionContext): Promise<Response> {
  const parts = url.pathname.split('/').filter(Boolean); const module = parts[1] ?? '';
  if (!sameOrigin(request, url)) return html(errorPage('Permintaan ditolak', 'Permintaan harus berasal dari website ini.'), 403);
  if (module === 'logout') { const token = cookie(request.headers.get('Cookie') ?? '', 'hd_session'); if (token) await env.DB.prepare('DELETE FROM sessions WHERE token_hash = ?').bind(await sha256(token)).run(); await audit(env, user.id, 'LOGOUT', 'USER', user.id, 'Logout'); return redirect(new URL('/admin/login', url), { 'Set-Cookie': 'hd_session=; Path=/; HttpOnly; SameSite=Lax; Max-Age=0' }); }
  if (!canManage(user.role, module)) return html(errorPage('Akses ditolak', 'Role Anda tidak memiliki izin untuk tindakan ini.'), 403);
  if (module === 'konten') return savePageContent(request, env, url, user);
  if (module === 'media' && parts[2] === 'upload') return uploadMedia(request, env, url, user);
  if (module === 'media' && parts[2]) return parts[3] === 'delete' ? deleteMedia(env, url, user, parts[2]) : updateMedia(request, env, url, user, parts[2]);
  if (module === 'pesan-masuk' && parts[3] === 'status') return updateInquiry(request, env, url, user, parts[2]);
  if (module === 'pengaturan') return saveSettings(request, env, url, user);
  if (module === 'pengguna') return parts[2] ? updateUser(request, env, url, user, parts[2]) : createUser(request, env, url, user);
  const kind = contentRoutes[module]; if (kind) return saveContent(request, env, url, user, kind, parts[2], parts[3]);
  return html(errorPage('Aksi tidak ditemukan', 'Tindakan admin ini tidak tersedia.'), 404);
}
function sameOrigin(request: Request, url: URL) { const value = request.headers.get('Origin') ?? request.headers.get('Referer'); if (!value) return true; try { return new URL(value).origin === url.origin; } catch { return false; } }
async function savePageContent(request: Request, env: RuntimeEnv, url: URL, user: User) { const form = await request.formData(); const key = clean(form.get('key'), 80); const allowed = new Set(['hero','about','services_home','projects_home','why_hd','process','final_cta']); if (!allowed.has(key)) return html(errorPage('Section tidak valid', 'Pilih section homepage yang tersedia.'), 422); const heading = clean(form.get('heading'), 180); const body = clean(form.get('body'), 3000); const requiresHeading = ['hero','services_home','projects_home','process','final_cta'].includes(key); if (!body || (requiresHeading && !heading)) return html(errorPage('Konten belum lengkap', 'Lengkapi seluruh field wajib pada section ini.'), 422); const data = JSON.stringify({ eyebrow: clean(form.get('eyebrow'), 80), heading, body, cta_label: clean(form.get('cta_label'), 80), cta_href: clean(form.get('cta_href'), 200) }); const status = clean(form.get('status'), 20) === 'PUBLISHED' ? 'PUBLISHED' : 'DRAFT'; await env.DB.prepare('INSERT INTO page_content (key,data,status,active,updated_at) VALUES (?,?,?,?,CURRENT_TIMESTAMP) ON CONFLICT(key) DO UPDATE SET data=excluded.data,status=excluded.status,active=excluded.active,updated_at=CURRENT_TIMESTAMP').bind(key,data,status,form.get('active') ? 1 : 0).run(); await audit(env,user.id,'UPDATE','PAGE_CONTENT',key,`Memperbarui section ${key}`); return redirect(new URL(`/admin/konten?section=${key}`,url)); }
async function saveContent(request: Request, env: RuntimeEnv, url: URL, user: User, kind: ContentKind, id?: string, action?: string) { const form = await request.formData(); const itemId = clean(form.get('id')) || id; if (action === 'delete' && itemId) { await env.DB.prepare("UPDATE content_items SET status = 'ARCHIVED', updated_at = CURRENT_TIMESTAMP WHERE id = ? AND kind = ?").bind(itemId, kind).run(); await audit(env,user.id,'ARCHIVE',kind,itemId,'Konten diarsipkan'); return redirect(new URL(`/admin/${routeFor(kind)}`,url)); } const title = clean(form.get('title'), 180), slug = clean(form.get('slug'), 120); if (!title || !/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(slug)) return html(errorPage('Data belum valid', 'Judul wajib diisi dan slug harus memakai huruf kecil, angka, serta tanda hubung.'),422); const data = JSON.stringify(Object.fromEntries(extraFields[kind].map(field => [field.key, clean(form.get(`meta_${field.key}`), 3000)]))); const fields = [title,slug,clean(form.get('category'),80),clean(form.get('summary'),500),clean(form.get('body'),12000),data,clean(form.get('seo_title'),180),clean(form.get('meta_description'),160),clean(form.get('canonical_url'),500),clean(form.get('index_status'),20) || 'INDEX_FOLLOW',clean(form.get('status'),20) || 'DRAFT',form.get('featured') ? 1 : 0]; try { if (itemId) { const previous = await env.DB.prepare('SELECT slug FROM content_items WHERE id = ? AND kind = ?').bind(itemId,kind).first<{slug:string}>(); await env.DB.prepare('UPDATE content_items SET title=?,slug=?,category=?,summary=?,body=?,data=?,seo_title=?,meta_description=?,canonical_url=?,index_status=?,status=?,featured=?,published_at=CASE WHEN ? = \'PUBLISHED\' AND published_at IS NULL THEN CURRENT_TIMESTAMP ELSE published_at END,updated_at=CURRENT_TIMESTAMP WHERE id=? AND kind=?').bind(...fields,fields[10],itemId,kind).run(); if (previous?.slug && previous.slug !== slug) await env.DB.prepare('INSERT INTO redirects (id,from_path,to_path,status_code) VALUES (?,?,?,301) ON CONFLICT(from_path) DO UPDATE SET to_path=excluded.to_path,status_code=301').bind(crypto.randomUUID(),`/${routeFor(kind)}/${previous.slug}`,`/${routeFor(kind)}/${slug}`).run(); await audit(env,user.id,'UPDATE',kind,itemId,`Memperbarui ${title}`); } else { const newId=crypto.randomUUID(); await env.DB.prepare('INSERT INTO content_items (id,kind,title,slug,category,summary,body,data,seo_title,meta_description,canonical_url,index_status,status,featured,published_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,CASE WHEN ? = \'PUBLISHED\' THEN CURRENT_TIMESTAMP END)').bind(newId,kind,...fields,fields[10]).run(); await audit(env,user.id,'CREATE',kind,newId,`Membuat ${title}`); } } catch { return html(errorPage('Slug sudah digunakan', 'Gunakan slug unik untuk item ini.'),409); } return redirect(new URL(`/admin/${routeFor(kind)}`,url)); }
async function updateInquiry(request: Request, env: RuntimeEnv, url: URL, user: User, id: string) { const form=await request.formData(); const status=clean(form.get('status'),20); if (!['NEW','CONTACTED','QUALIFIED','CLOSED','SPAM'].includes(status)) return html(errorPage('Status tidak valid','Pilih status inquiry yang tersedia.'),422); await env.DB.prepare('UPDATE inquiries SET status=?,internal_note=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').bind(status,clean(form.get('internal_note'),3000),id).run(); await audit(env,user.id,'UPDATE_STATUS','INQUIRY',id,`Status inquiry menjadi ${status}`); return Response.redirect(new URL(`/admin/pesan-masuk/${id}`,url),302); }
async function saveSettings(request: Request, env: RuntimeEnv, url: URL, user: User) { const form=await request.formData(); const keys=['company_name','tagline','site_description','phone','email','address','instagram_url','facebook_url','linkedin_url','whatsapp_number','whatsapp_template','site_url','default_title','default_meta_description','ga4_measurement_id','gtm_id']; for (const key of keys) await env.DB.prepare('INSERT INTO site_settings (key,value,updated_at) VALUES (?,?,CURRENT_TIMESTAMP) ON CONFLICT(key) DO UPDATE SET value=excluded.value,updated_at=CURRENT_TIMESTAMP').bind(key,clean(form.get(key),500)).run(); await audit(env,user.id,'UPDATE','SETTINGS',null,'Memperbarui pengaturan global'); return redirect(new URL('/admin/pengaturan',url)); }
async function createUser(request: Request, env: RuntimeEnv, url: URL, user: User) { if (user.role !== 'SUPER_ADMIN') return html(errorPage('Akses ditolak','Hanya super admin yang dapat mengelola pengguna.'),403); const form=await request.formData(); const email=clean(form.get('email'),254).toLowerCase(), password=String(form.get('password') ?? ''), role=clean(form.get('role'),20); if (!email || password.length < 12 || !['EDITOR','SUPER_ADMIN'].includes(role)) return html(errorPage('Data pengguna tidak valid','Gunakan email valid, password minimal 12 karakter, dan role yang tersedia.'),422); const result=await passwordHash(password); try { const id=crypto.randomUUID(); await env.DB.prepare('INSERT INTO users (id,name,email,password_hash,password_salt,role) VALUES (?,?,?,?,?,?)').bind(id,clean(form.get('name'),100),email,result.hash,result.salt,role).run(); await audit(env,user.id,'CREATE','USER',id,`Membuat user ${email}`); } catch { return html(errorPage('Email sudah digunakan','Gunakan email admin lain.'),409); } return Response.redirect(new URL('/admin/pengguna',url),302); }
async function updateUser(request: Request, env: RuntimeEnv, url: URL, actor: User, id: string) { if (actor.role !== 'SUPER_ADMIN') return html(errorPage('Akses ditolak','Hanya super admin yang dapat mengelola pengguna.'),403); const target = await env.DB.prepare('SELECT id, role, status FROM users WHERE id = ?').bind(id).first<{id:string;role:Role;status:string}>(); if (!target) return html(errorPage('Pengguna tidak ditemukan','Pengguna yang ingin diubah tidak tersedia.'),404); const form = await request.formData(); const role = clean(form.get('role'),20) as Role, status = clean(form.get('status'),20), password = String(form.get('password') ?? ''); if (!['EDITOR','SUPER_ADMIN'].includes(role) || !['ACTIVE','DISABLED'].includes(status) || (password && password.length < 12)) return html(errorPage('Data pengguna tidak valid','Role/status tidak tersedia atau password kurang dari 12 karakter.'),422); if (!canChangeAdmin(actor,target,role,status)) return html(errorPage('Akses ditolak','Anda tidak dapat menurunkan role atau menonaktifkan akun sendiri.'),403); if (target.role === 'SUPER_ADMIN' && (role !== 'SUPER_ADMIN' || status !== 'ACTIVE')) { const admins = await env.DB.prepare("SELECT COUNT(*) AS total FROM users WHERE role = 'SUPER_ADMIN' AND status = 'ACTIVE'").first<{total:number}>(); if (Number(admins?.total) < 2) return html(errorPage('Aksi ditolak','Setidaknya satu super admin aktif harus tetap tersedia.'),422); } if (password) { const result = await passwordHash(password); await env.DB.prepare('UPDATE users SET role = ?, status = ?, password_hash = ?, password_salt = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?').bind(role,status,result.hash,result.salt,id).run(); } else await env.DB.prepare('UPDATE users SET role = ?, status = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?').bind(role,status,id).run(); if (status === 'DISABLED') await env.DB.prepare('DELETE FROM sessions WHERE user_id = ?').bind(id).run(); await audit(env,actor.id,password ? 'RESET_PASSWORD' : 'UPDATE','USER',id,password ? 'Mereset password pengguna' : `Mengubah role/status pengguna menjadi ${role}/${status}`); return redirect(new URL('/admin/pengguna',url)); }

async function uploadMedia(request: Request, env: RuntimeEnv, url: URL, user: User) { const form=await request.formData(); const file=form.get('file'); if (!(file instanceof File)) return html(errorPage('File tidak tersedia','Pilih file yang ingin diupload.'),422); const allowed=new Map([['image/jpeg',10*1024*1024],['image/png',10*1024*1024],['image/webp',10*1024*1024],['image/avif',10*1024*1024],['application/pdf',20*1024*1024]]); if (!allowed.has(file.type) || file.size > allowed.get(file.type)!) return html(errorPage('Upload ditolak','Format atau ukuran file tidak sesuai. Maksimum gambar 10 MB dan PDF 20 MB.'),422); const bytes=new Uint8Array(await file.arrayBuffer()); if (!validMagic(bytes,file.type)) return html(errorPage('Upload ditolak','Isi file tidak sesuai dengan format yang dipilih.'),422); const id=crypto.randomUUID(); const extension=extensionFor(file.type); const objectKey=`media/${id}.${extension}`; await env.MEDIA.put(objectKey,bytes,{httpMetadata:{contentType:file.type,cacheControl:'public, max-age=31536000, immutable'}}); await env.DB.prepare('INSERT INTO media (id,object_key,original_filename,content_type,size,alt,caption,uploader_id) VALUES (?,?,?,?,?,?,?,?)').bind(id,objectKey,clean(file.name,255),file.type,file.size,clean(form.get('alt'),250),clean(form.get('caption'),500),user.id).run(); await audit(env,user.id,'UPLOAD','MEDIA',id,`Mengunggah ${file.name}`); return Response.redirect(new URL('/admin/media',url),302); }
async function updateMedia(request: Request, env: RuntimeEnv, url: URL, user: User, id: string) { const form = await request.formData(); const alt = clean(form.get('alt'),250); if (!alt) return html(errorPage('Alt text wajib', 'Isi alt text yang menjelaskan media.'),422); const result = await env.DB.prepare('UPDATE media SET alt = ?, caption = ? WHERE id = ?').bind(alt,clean(form.get('caption'),500),id).run(); if (!result.meta.changes) return html(errorPage('Media tidak ditemukan','Media yang ingin diperbarui tidak tersedia.'),404); await audit(env,user.id,'UPDATE','MEDIA',id,'Memperbarui metadata media'); return redirect(new URL('/admin/media',url)); }
async function deleteMedia(env: RuntimeEnv, url: URL, user: User, id: string) { const item = await env.DB.prepare('SELECT object_key, original_filename FROM media WHERE id = ?').bind(id).first<{object_key:string;original_filename:string}>(); if (!item) return html(errorPage('Media tidak ditemukan','Media yang ingin dihapus tidak tersedia.'),404); await env.MEDIA.delete(item.object_key); await env.DB.prepare('DELETE FROM media WHERE id = ?').bind(id).run(); await audit(env,user.id,'DELETE','MEDIA',id,`Menghapus ${item.original_filename}`); return redirect(new URL('/admin/media',url)); }
function extensionFor(type: string) { return ({'image/jpeg':'jpg','image/png':'png','image/webp':'webp','image/avif':'avif','application/pdf':'pdf'} as Record<string,string>)[type] ?? 'bin'; }
function validMagic(bytes: Uint8Array, type: string) { const starts=(...values:number[])=>values.every((value,index)=>bytes[index]===value); if(type==='image/jpeg') return starts(0xff,0xd8,0xff); if(type==='image/png') return starts(0x89,0x50,0x4e,0x47); if(type==='image/webp') return String.fromCharCode(...bytes.slice(0,4))==='RIFF' && String.fromCharCode(...bytes.slice(8,12))==='WEBP'; if(type==='application/pdf') return String.fromCharCode(...bytes.slice(0,4))==='%PDF'; if(type==='image/avif') return String.fromCharCode(...bytes.slice(4,12)).includes('ftyp'); return false; }
async function media(request: Request, env: RuntimeEnv, id: string) { const record=await env.DB.prepare('SELECT object_key,content_type FROM media WHERE id=?').bind(id).first<{object_key:string;content_type:string}>(); if(!record) return new Response('Not found',{status:404}); const object=await env.MEDIA.get(record.object_key); if(!object) return new Response('Not found',{status:404}); const headers=new Headers({'Content-Type':record.content_type,'Cache-Control':'public, max-age=31536000, immutable','X-Content-Type-Options':'nosniff'}); object.writeHttpMetadata(headers); return new Response(object.body,{headers}); }

async function api(request: Request, env: RuntimeEnv, url: URL, ctx: ExecutionContext): Promise<Response> { if(url.pathname==='/api/inquiries' && request.method==='POST') return createInquiry(request,env,url,ctx); return Response.json({error:{code:'NOT_FOUND',message:'API tidak ditemukan'}},{status:404,headers:{'X-Content-Type-Options':'nosniff'}}); }
async function createInquiry(request: Request, env: RuntimeEnv, url: URL, ctx: ExecutionContext) { const length=Number(request.headers.get('Content-Length') ?? 0); if(length>32*1024) return html(errorPage('Pesan terlalu besar','Ringkas pesan Anda lalu coba lagi.'),413); const form=await request.formData(); const name=clean(form.get('name'),100),phone=clean(form.get('phone'),50),message=clean(form.get('message'),3000); if(!name||!phone||!message) return html(errorPage('Data belum lengkap','Nama, nomor telepon, dan pesan wajib diisi.'),422); const id=crypto.randomUUID(), reference=`HD-${new Date().toISOString().slice(0,10).replaceAll('-','')}-${id.slice(0,6).toUpperCase()}`; await env.DB.prepare('INSERT INTO inquiries (id,reference,name,phone,service,message,source) VALUES (?,?,?,?,?,?,?)').bind(id,reference,name,phone,clean(form.get('service'),100),message,'website').run(); ctx.waitUntil(audit(env,null,'CREATE','INQUIRY',id,`Inquiry ${reference} diterima`)); return html(publicLayout('Inquiry terkirim','Terima kasih sudah menghubungi HD Karya Bandung.',`<h1>Terima kasih</h1><p>Inquiry Anda telah dicatat dengan referensi <strong>${escape(reference)}</strong>. Tim kami akan menindaklanjuti melalui nomor yang Anda berikan.</p><a class="button button-accent" href="/">Kembali ke beranda</a>`),201); }

function robots(url: URL) { return `User-agent: *\nAllow: /\nDisallow: /admin/\nDisallow: /api/\n\nSitemap: ${url.origin}/sitemap.xml\n`; }
async function sitemap(url: URL, env: RuntimeEnv) { const rows=await env.DB.prepare("SELECT kind,slug,updated_at FROM content_items WHERE status='PUBLISHED' AND index_status='INDEX_FOLLOW' AND slug IS NOT NULL").all<{kind:ContentKind;slug:string;updated_at:string}>(); const fixed=['/','/tentang-kami','/layanan','/proyek','/galeri','/artikel','/kontak']; const locations=[...fixed.map(path=>({path,lastmod:new Date().toISOString().slice(0,10)})),...rows.results.map(row=>({path:`/${routeFor(row.kind)}/${row.slug}`,lastmod:row.updated_at.slice(0,10)}))]; const xml=`<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${locations.map(item=>`<url><loc>${escapeXml(url.origin+item.path)}</loc><lastmod>${escapeXml(item.lastmod)}</lastmod></url>`).join('')}</urlset>`; return text(xml,{'Content-Type':'application/xml; charset=utf-8','Cache-Control':'public, max-age=3600'}); }
function escapeXml(value:string) { return value.replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&apos;','"':'&quot;'}[char]!)); }
